DROP TABLE IF EXISTS `hotel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotel` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL COMMENT '酒店名称',
  `city` varchar(50) NOT NULL COMMENT '所在城市',
  `address` varchar(500) NOT NULL COMMENT '详细地址',
  `rating` decimal(10,2) DEFAULT NULL,
  `star` tinyint DEFAULT '3' COMMENT '星级(3-5)',
  `tags` varchar(500) DEFAULT NULL COMMENT '标签JSON(如: 靠近地铁, 免费停车)',
  `facilities` text COMMENT '设施JSON',
  `description` text COMMENT '酒店介绍',
  `cover_image` varchar(500) DEFAULT NULL COMMENT '封面图',
  `images` text COMMENT '图集JSON',
  `price_start` decimal(10,2) DEFAULT NULL COMMENT '起步价',
  `status` int DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  `review_count` int DEFAULT '0' COMMENT '评论数',
  `student_discount` decimal(5,2) DEFAULT '0.00' COMMENT '学生折扣比例(%)',
  `student_price` decimal(10,2) DEFAULT NULL COMMENT '学生价',
  `student_friendly` tinyint DEFAULT '0' COMMENT '是否学生友好：0-否 1-是',
  `created_at` datetime(6) DEFAULT NULL,
  `distance_info` varchar(256) DEFAULT NULL,
  `has_accessible_rooms` bit(1) DEFAULT NULL,
  `has_student_discount` bit(1) DEFAULT NULL,
  `image_url` varchar(512) DEFAULT NULL,
  `starting_price` int DEFAULT NULL,
  `amenities` varchar(128) DEFAULT NULL,
  `district` varchar(64) DEFAULT NULL,
  `has_accessible_room` bit(1) DEFAULT NULL,
  `has_elevator` bit(1) DEFAULT NULL,
  `has_wheelchair_access` bit(1) DEFAULT NULL,
  `location` varchar(128) DEFAULT NULL,
  `original_price` decimal(10,2) DEFAULT NULL,
  `photo_url` varchar(256) DEFAULT NULL,
  `star_level` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_city` (`city`),
  KEY `idx_price` (`price_start`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='酒店表';
/*!40101 SET character_set_client = @saved_cs_client */;

