DROP TABLE IF EXISTS `hotel_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotel_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) NOT NULL COMMENT '订单号',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `hotel_id` bigint NOT NULL COMMENT '酒店ID',
  `hotel_name` varchar(200) DEFAULT NULL COMMENT '酒店名称',
  `room_id` bigint NOT NULL COMMENT '房型ID',
  `room_name` varchar(100) DEFAULT NULL COMMENT '房型名称',
  `check_in` date NOT NULL COMMENT '入住日期',
  `check_out` date NOT NULL COMMENT '离店日期',
  `night_count` int DEFAULT NULL COMMENT '居住晚数',
  `room_count` int DEFAULT '1' COMMENT '房间数',
  `total_price` decimal(10,2) NOT NULL COMMENT '总价',
  `contact_name` varchar(50) DEFAULT NULL COMMENT '入住人',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `status` varchar(20) DEFAULT 'paid' COMMENT '状态: pending, paid, cancelled',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  `travelers_info` text COMMENT '入住人信息JSON',
  `student_discount` decimal(10,2) DEFAULT '0.00' COMMENT '学生优惠金额',
  `final_amount` decimal(10,2) DEFAULT NULL COMMENT '最终支付金额',
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_no` (`order_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_hotel_id` (`hotel_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='酒店订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `hotel_order` WRITE;
/*!40000 ALTER TABLE `hotel_order` DISABLE KEYS */;
