DROP TABLE IF EXISTS `hotel_room`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotel_room` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `hotel_id` bigint NOT NULL COMMENT '酒店ID',
  `name` varchar(100) NOT NULL COMMENT '房型名称',
  `image` varchar(500) DEFAULT NULL COMMENT '房型图片',
  `bed_type` varchar(50) DEFAULT NULL COMMENT '床型',
  `breakfast` varchar(50) DEFAULT NULL COMMENT '早餐情况',
  `people` int DEFAULT '2' COMMENT '入住人数',
  `price` decimal(10,2) NOT NULL COMMENT '价格',
  `stock` int DEFAULT '10' COMMENT '每日库存',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  `cancellation_policy` varchar(32) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `description` text,
  `max_occupancy` int DEFAULT NULL,
  `photo_urls` varchar(256) DEFAULT NULL,
