INSERT INTO `line` VALUES (1,'出发前7天可免费取消，3天内扣除50%费用',3,'一次性打卡川西双骄，高性价比之选','九寨沟,黄龙','餐费,个人消费,景区内交通','往返交通,2晚住宿,景区门票,旅游保险','[{\"title\":\"Day1 成都-九寨沟\",\"content\":\"早上从成都出发，沿途欣赏羌族风情，抵达九寨沟后游览树正沟\"},{\"title\":\"Day2 九寨沟全天\",\"content\":\"全天游览九寨沟五彩池、诺日朗瀑布等景点\"},{\"title\":\"Day3 黄龙-成都\",\"content\":\"上午游览黄龙景区，下午返回成都\"}]','川西环线·九寨沟+黄龙3天2晚纯玩游',2,888.00,'https://via.placeholder.com/400x200/4A90D9/FFFFFF?text=九寨沟',1,588.00,'纯玩,学生优惠,热门'),(2,'出发前7天可免费取消，5天内扣除30%费用',4,'挑战玻璃栈道，探索奇峰怪石','天门山,张家界国家森林公园,凤凰古城','餐费,玻璃栈道鞋套,个人消费','往返交通,3晚住宿,景区门票,景区交通','[{\"title\":\"Day1 出发地-张家界\",\"content\":\"抵达张家界，入住酒店\"},{\"title\":\"Day2 天门山\",\"content\":\"游览天门山，挑战玻璃栈道\"},{\"title\":\"Day3 张家界国家森林公园\",\"content\":\"全天游览袁家界、金鞭溪\"},{\"title\":\"Day4 凤凰古城\",\"content\":\"游览凤凰古城，下午返程\"}]','张家界天门山4天3晚深度游',3,1288.00,'https://via.placeholder.com/400x200/27AE60/FFFFFF?text=张家界',1,988.00,'探险,摄影,学生优惠'),(3,'出发前10天可免费取消，7天内扣除30%费用',6,'洱海骑行，丽江古城，泸沽湖','大理,丽江,泸沽湖','餐费,环湖骑行租车费,个人消费','全程交通,5晚特色民宿,景区门票','[{\"title\":\"Day1 各地-大理\",\"content\":\"抵达大理，入住洱海海景房\"},{\"title\":\"Day2 大理环湖\",\"content\":\"洱海骑行，游览双廊、喜洲\"},{\"title\":\"Day3 大理-丽江\",\"content\":\"前往丽江，游览丽江古城\"},{\"title\":\"Day4 玉龙雪山\",\"content\":\"游览玉龙雪山，蓝月谷\"},{\"title\":\"Day5 泸沽湖\",\"content\":\"前往泸沽湖，体验摩梭文化\"},{\"title\":\"Day6 返程\",\"content\":\"泸沽湖返回，结束旅程\"}]','云南大理+丽江6天5晚浪漫游',5,1688.00,'https://via.placeholder.com/400x200/E74C3C/FFFFFF?text=云南',1,1388.00,'浪漫,休闲,打卡');
