INSERT INTO `review` VALUES (1,1,1,NULL,5,'非常棒的旅行体验！导游很专业，行程安排合理，风景太美了！',NULL,'2026-01-22 13:52:27',0,NULL,NULL,NULL),(2,2,1,NULL,4,'整体不错，就是行程有点赶，建议多留点自由活动时间。',NULL,'2026-01-22 13:52:27',0,NULL,NULL,NULL),(3,1,2,NULL,5,'三亚的海水太清澈了，蜈支洲岛超级美！',NULL,'2026-01-22 13:52:27',0,NULL,NULL,NULL),(4,1,1,NULL,5,'非常棒的旅行体验！导游很专业，行程安排合理，风景太美了！',NULL,'2026-01-22 22:50:05',0,NULL,NULL,NULL),(5,2,1,NULL,4,'整体不错，就是行程有点赶，建议多留点自由活动时间。',NULL,'2026-01-22 22:50:05',0,NULL,NULL,NULL),(6,3,1,NULL,5,'云南真的太美了，下次还要来！',NULL,'2026-01-22 22:50:05',0,NULL,NULL,NULL),(7,1,2,NULL,5,'三亚的海水太清澈了，蜈支洲岛超级美！',NULL,'2026-01-22 22:50:05',0,NULL,NULL,NULL),(8,2,2,NULL,5,'酒店很棒，服务也很好，强烈推荐！',NULL,'2026-01-22 22:50:05',0,NULL,NULL,NULL),(9,1,6,NULL,4,'故宫很震撼，长城也很壮观，就是人太多了。',NULL,'2026-01-22 22:50:05',0,NULL,NULL,NULL),(10,3,6,NULL,5,'北京不愧是古都，历史文化底蕴深厚。',NULL,'2026-01-22 22:50:05',0,NULL,NULL,NULL),(11,5,7,NULL,5,'模糊','[\"blob:http://localhost:3000/e5a8e8b3-c68f-40e3-99c0-20015144fc01\"]','2026-02-13 22:28:35',0,NULL,NULL,'住宿舒适');
/*!40000 ALTER TABLE `review` ENABLE KEYS */;
UNLOCK TABLES;
