DROP TABLE IF EXISTS `student_auth_application`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_auth_application` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `user_name` varchar(100) DEFAULT NULL COMMENT '用户姓名',
  `user_phone` varchar(20) DEFAULT NULL COMMENT '用户手机号',
  `school_name` varchar(100) DEFAULT NULL COMMENT '学校名称',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `grade` varchar(20) DEFAULT NULL COMMENT '年级',
  `student_card` varchar(500) DEFAULT NULL COMMENT '学生证照片URL',
  `status` tinyint DEFAULT '0' COMMENT '状态：0-待审核 1-已通过 2-已拒绝',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '拒绝原因',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(100) DEFAULT NULL COMMENT '审核人姓名',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  `real_name` varchar(100) DEFAULT NULL COMMENT '真实姓名',
  `student_id` varchar(50) DEFAULT NULL COMMENT '学号',
  `id_card_front` varchar(500) DEFAULT NULL COMMENT '身份证正面照片URL',
  `id_card_back` varchar(500) DEFAULT NULL COMMENT '身份证反面照片URL',
  `chsi_screenshot` varchar(500) DEFAULT NULL COMMENT '学信网截图URL',
  `valid_start_date` date DEFAULT NULL COMMENT '有效期开始',
  `valid_end_date` date DEFAULT NULL COMMENT '有效期结束',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生认证申请表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `student_auth_application` WRITE;
/*!40000 ALTER TABLE `student_auth_application` DISABLE KEYS */;
/*!40000 ALTER TABLE `student_auth_application` ENABLE KEYS */;
UNLOCK TABLES;
