  `includes` text COMMENT '费用包含JSON',
  `excludes` text COMMENT '费用不含JSON',
  `stock` int DEFAULT '100' COMMENT '库存',
  `sales` int DEFAULT '0' COMMENT '销量',
  `rating` decimal(2,1) DEFAULT '5.0' COMMENT '评分',
  `review_count` int DEFAULT '0' COMMENT '评价数',
  `status` tinyint DEFAULT '1' COMMENT '状态: 0-下架 1-上架',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  `category` varchar(50) DEFAULT NULL COMMENT '分类',
  `tags` varchar(200) DEFAULT NULL COMMENT '标签',
  `student_discount` decimal(5,2) DEFAULT '0.00' COMMENT '学生折扣比例(%)',
  `student_price` decimal(10,2) DEFAULT NULL COMMENT '学生价',
  `student_friendly` tinyint DEFAULT '0' COMMENT '是否学生友好：0-否 1-是',
  PRIMARY KEY (`id`),
  KEY `idx_destination` (`destination`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='旅游线路表';
