INSERT INTO `tour_line` VALUES (1,'云南大理丽江双飞6日游','https://picsum.photos/800/400?random=1','[\"https://picsum.photos/800/400?random=11\",\"https://picsum.photos/800/400?random=12\"]','云南','上海',2999.00,6,'感受彩云之南的魅力','[{\"title\":\"上海-昆明\",\"content\":\"乘机前往春城昆明\"},{\"title\":\"昆明-大理\",\"content\":\"游览洱海、崇圣寺三塔\"}]','[\"往返机票\",\"5晚酒店住宿\",\"行程内用餐\",\"景点首道门票\"]','[\"个人消费\",\"单房差\",\"自费项目\"]',50,356,4.8,128,1,'2026-01-22 13:52:27','2026-11-11 23:09:48',0,'周末游',',自然',0.00,NULL,0),(2,'海南三亚阳光5日游','https://picsum.photos/800/400?random=2','[\"https://picsum.photos/800/400?random=21\"]','海南','上海',3599.00,5,'享受阳光沙滩','[{\"title\":\"上海-三亚\",\"content\":\"乘机前往三亚\"}]','[\"往返机票\",\"4晚海景酒店\"]','[\"个人消费\",\"水上项目\"]',80,520,4.9,256,1,'2026-01-22 13:52:27','2026-11-11 23:09:48',0,'海岛度假',',自然',0.00,NULL,0),(3,'四川九寨沟黄龙4日游','https://picsum.photos/800/400?random=3','[\"https://picsum.photos/800/400?random=31\"]','四川','成都',2599.00,4,'探索人间仙境','[{\"title\":\"成都-九寨沟\",\"content\":\"乘车前往九寨沟\"}]','[\"往返大巴\",\"3晚酒店\"]','[\"个人消费\",\"索道费用\"]',40,189,4.7,89,1,'2026-01-22 13:52:27','2026-11-11 23:09:48',0,'学生特惠',',自然',0.00,NULL,0),(4,'西藏拉萨林芝7日游','https://picsum.photos/800/400?random=4','[\"https://picsum.photos/800/400?random=41\"]','西藏','上海',4999.00,7,'心灵的净土之旅','[{\"title\":\"上海-拉萨\",\"content\":\"乘机前往拉萨\"}]','[\"往返机票\",\"6晚酒店\",\"氧气供应\"]','[\"个人消费\",\"单房差\"]',30,98,4.9,45,1,'2026-01-22 13:52:27','2026-11-11 23:09:48',0,'周末游',',自然',0.00,NULL,0),(5,'北京故宫长城4日游','https://picsum.photos/800/400?random=6','[\"https://picsum.photos/800/400?random=61\"]','北京','上海',1999.00,4,'探访古都北京','[{\"title\":\"上海-北京\",\"content\":\"乘高铁前往北京\"}]','[\"往返高铁\",\"3晚酒店\",\"景点门票\"]','[\"个人消费\",\"用餐\"]',100,890,4.8,456,1,'2026-01-22 13:52:27','2026-11-11 23:09:48',0,'海岛度假',',自然',0.00,NULL,0),(7,'云南大理丽江双飞6日游','https://picsum.photos/800/400?random=1','[\"https://picsum.photos/800/400?random=11\",\"https://picsum.photos/800/400?random=12\",\"https://picsum.photos/800/400?random=13\"]','云南','上海',2999.00,6,'感受彩云之南的魅力，游览大理古城、洱海、丽江古城、玉龙雪山等著名景点。','[{\"title\":\"上海-昆明\",\"content\":\"乘机前往春城昆明，接机后入住酒店休息。\"},{\"title\":\"昆明-大理\",\"content\":\"乘车前往大理，游览洱海、崇圣寺三塔。\"},{\"title\":\"大理古城\",\"content\":\"游览大理古城，体验白族文化。\"},{\"title\":\"大理-丽江\",\"content\":\"前往丽江，游览束河古镇。\"},{\"title\":\"玉龙雪山\",\"content\":\"游览玉龙雪山，蓝月谷。\"},{\"title\":\"丽江-上海\",\"content\":\"自由活动后乘机返回上海。\"}]','[\"往返机票\",\"5晚酒店住宿\",\"行程内用餐\",\"景点首道门票\",\"旅游大巴\",\"导游服务\"]','[\"个人消费\",\"单房差\",\"自费项目\",\"旅游意外险\"]',50,356,5.0,1,1,'2026-01-22 22:50:05','2026-01-22 22:50:05',0,'假期游','古城,摄影,自然',0.00,NULL,0),(8,'海南三亚阳光5日游','https://picsum.photos/800/400?random=2','[\"https://picsum.photos/800/400?random=21\",\"https://picsum.photos/800/400?random=22\"]','海南','上海',3599.00,5,'享受阳光沙滩，体验热带风情，游览天涯海角、南山寺、蜈支洲岛等。','[{\"title\":\"上海-三亚\",\"content\":\"乘机前往三亚，接机后入住酒店。\"},{\"title\":\"蜈支洲岛\",\"content\":\"全天游览蜈支洲岛，享受海岛风光。\"},{\"title\":\"南山文化旅游区\",\"content\":\"游览南山寺，参观108米海上观音。\"},{\"title\":\"天涯海角\",\"content\":\"游览天涯海角，亚龙湾热带天堂森林公园。\"},{\"title\":\"三亚-上海\",\"content\":\"自由活动后乘机返回。\"}]','[\"往返机票\",\"4晚海景酒店\",\"行程内用餐\",\"景点门票\",\"接送机\"]','[\"个人消费\",\"水上项目\",\"单房差\"]',80,520,4.9,256,1,'2026-01-22 22:50:05','2026-01-22 22:50:05',0,'假期游','海岛,亲子,度假',0.00,NULL,0),(9,'四川九寨沟黄龙4日游','https://picsum.photos/800/400?random=3','[\"https://picsum.photos/800/400?random=31\",\"https://picsum.photos/800/400?random=32\"]','四川','成都',2599.00,4,'探索人间仙境九寨沟，欣赏黄龙五彩池，感受大自然的鬼斧神工。','[{\"title\":\"成都-九寨沟\",\"content\":\"乘车前往九寨沟，沿途欣赏川西风光。\"},{\"title\":\"九寨沟全天游\",\"content\":\"全天游览九寨沟，五花海、珍珠滩瀑布等。\"},{\"title\":\"黄龙风景区\",\"content\":\"游览黄龙风景区，五彩池、迎宾池等。\"},{\"title\":\"九寨沟-成都\",\"content\":\"返回成都，结束愉快旅程。\"}]','[\"往返大巴\",\"3晚酒店\",\"行程用餐\",\"景点门票\",\"导游服务\"]','[\"个人消费\",\"索道费用\",\"单房差\"]',40,189,4.7,89,1,'2026-01-22 22:50:05','2026-01-22 22:50:05',0,'周末游','自然,摄影,徒步',0.00,NULL,0),(10,'西藏拉萨林芝7日游','https://picsum.photos/800/400?random=4','[\"https://picsum.photos/800/400?random=41\",\"https://picsum.photos/800/400?random=42\"]','西藏','上海',4999.00,7,'心灵的净土之旅，游览布达拉宫、大昭寺、纳木错、林芝桃花沟等。','[{\"title\":\"上海-拉萨\",\"content\":\"乘机前往拉萨，适应高原环境。\"},{\"title\":\"拉萨市区\",\"content\":\"游览布达拉宫、大昭寺、八廓街。\"},{\"title\":\"拉萨-林芝\",\"content\":\"乘车前往林芝，沿途欣赏尼洋河风光。\"},{\"title\":\"林芝\",\"content\":\"游览雅鲁藏布大峡谷、南迦巴瓦峰。\"},{\"title\":\"林芝-拉萨\",\"content\":\"返回拉萨，途经巴松措。\"},{\"title\":\"纳木错\",\"content\":\"游览圣湖纳木错，感受高原湖泊之美。\"},{\"title\":\"拉萨-上海\",\"content\":\"乘机返回上海。\"}]','[\"往返机票\",\"6晚酒店\",\"行程用餐\",\"景点门票\",\"旅游车\",\"导游\",\"氧气供应\"]','[\"个人消费\",\"单房差\",\"自费项目\"]',30,98,4.9,45,1,'2026-01-22 22:50:05','2026-01-22 22:50:05',0,'假期游','高原,朝圣,摄影',0.00,NULL,0),(11,'新疆天山天池5日游','https://picsum.photos/800/400?random=5','[\"https://picsum.photos/800/400?random=51\",\"https://picsum.photos/800/400?random=52\"]','新疆','上海',3299.00,5,'探索西域风情，游览天山天池、吐鲁番、火焰山等著名景点。','[{\"title\":\"上海-乌鲁木齐\",\"content\":\"乘机前往乌鲁木齐，入住酒店。\"},{\"title\":\"天山天池\",\"content\":\"游览天山天池，欣赏高山湖泊美景。\"},{\"title\":\"吐鲁番\",\"content\":\"游览火焰山、葡萄沟、坎儿井。\"},{\"title\":\"乌鲁木齐\",\"content\":\"游览国际大巴扎，品尝新疆美食。\"},{\"title\":\"乌鲁木齐-上海\",\"content\":\"乘机返回上海。\"}]','[\"往返机票\",\"4晚酒店\",\"行程用餐\",\"景点门票\",\"旅游车\"]','[\"个人消费\",\"单房差\",\"区间车\"]',60,156,4.6,67,1,'2026-01-22 22:50:05','2026-01-22 22:50:05',0,'假期游','异域风情,美食,自然',0.00,NULL,0),(12,'北京故宫长城4日游','https://picsum.photos/800/400?random=6','[\"https://picsum.photos/800/400?random=61\",\"https://picsum.photos/800/400?random=62\"]','北京','上海',1999.00,4,'探访古都北京，游览故宫、长城、颐和园、天坛等世界文化遗产。','[{\"title\":\"上海-北京\",\"content\":\"乘高铁前往北京，入住酒店。\"},{\"title\":\"故宫天安门\",\"content\":\"游览天安门广场、故宫博物院。\"},{\"title\":\"长城\",\"content\":\"游览八达岭长城，体验不到长城非好汉。\"},{\"title\":\"颐和园-上海\",\"content\":\"游览颐和园后乘高铁返回。\"}]','[\"往返高铁\",\"3晚酒店\",\"景点门票\",\"导游服务\"]','[\"个人消费\",\"用餐\",\"单房差\"]',100,890,4.8,456,1,'2026-01-22 22:50:05','2026-01-22 22:50:05',0,'学生特惠','历史,古迹,研学',0.00,NULL,0),(13,'广东珠海长隆3日游','https://picsum.photos/800/400?random=7','[\"https://picsum.photos/800/400?random=71\",\"https://picsum.photos/800/400?random=72\"]','广东','上海',2199.00,3,'畅玩长隆海洋王国，观赏精彩表演，体验刺激游乐设施。','[{\"title\":\"上海-珠海\",\"content\":\"乘机前往珠海，入住长隆酒店。\"},{\"title\":\"海洋王国\",\"content\":\"全天畅玩长隆海洋王国。\"},{\"title\":\"珠海-上海\",\"content\":\"自由活动后乘机返回。\"}]','[\"往返机票\",\"2晚长隆酒店\",\"海洋王国门票\"]','[\"个人消费\",\"用餐\",\"其他娱乐项目\"]',120,678,4.7,234,1,'2026-01-22 22:50:05','2026-02-12 22:22:07',0,'亲子游','乐园,海岛,美食',0.00,NULL,0),(14,'浙江杭州西湖2日游','https://picsum.photos/800/400?random=8','[\"https://picsum.photos/800/400?random=81\",\"https://picsum.photos/800/400?random=82\"]','浙江','上海',899.00,2,'游览人间天堂杭州，西湖、灵隐寺、宋城千古情。','[{\"title\":\"上海-杭州\",\"content\":\"乘高铁前往杭州，游览西湖、雷峰塔。\"},{\"title\":\"灵隐寺-上海\",\"content\":\"游览灵隐寺后返回上海。\"}]','[\"往返高铁\",\"1晚酒店\",\"景点门票\"]','[\"个人消费\",\"用餐\",\"单房差\"]',200,1256,4.5,567,1,'2026-01-22 22:50:05','2026-02-12 22:22:07',0,'周末游','自然,古城,摄影',0.00,NULL,0),(15,'云南香格里拉5日游','https://picsum.photos/800/400?random=9','[\"https://picsum.photos/800/400?random=91\",\"https://picsum.photos/800/400?random=92\"]','云南','上海',3899.00,5,'探索消失的地平线，游览普达措、松赞林寺、虎跳峡等。','[{\"title\":\"上海-丽江\",\"content\":\"乘机前往丽江，入住酒店。\"},{\"title\":\"丽江-香格里拉\",\"content\":\"乘车前往香格里拉，途经虎跳峡。\"},{\"title\":\"普达措国家公园\",\"content\":\"全天游览普达措国家公园。\"},{\"title\":\"松赞林寺\",\"content\":\"游览松赞林寺，独克宗古城。\"},{\"title\":\"香格里拉-上海\",\"content\":\"乘机返回上海。\"}]','[\"往返机票\",\"4晚酒店\",\"行程用餐\",\"景点门票\",\"旅游车\"]','[\"个人消费\",\"单房差\",\"骑马费用\"]',35,123,4.8,56,1,'2026-01-22 22:50:05','2026-01-22 22:50:05',0,'结伴游','探险,自然,藏族文化',0.00,NULL,0),(16,'海南博鳌4日游','https://picsum.photos/800/400?random=10','[\"https://picsum.photos/800/400?random=101\",\"https://picsum.photos/800/400?random=102\"]','海南','上海',2899.00,4,'游览博鳌亚洲论坛永久会址，体验海南东线风光。','[{\"title\":\"上海-海口\",\"content\":\"乘机前往海口，入住酒店。\"},{\"title\":\"博鳌\",\"content\":\"游览博鳌亚洲论坛永久会址、玉带滩。\"},{\"title\":\"兴隆\",\"content\":\"游览兴隆热带植物园、咖啡谷。\"},{\"title\":\"海口-上海\",\"content\":\"游览骑楼老街后乘机返回。\"}]','[\"往返机票\",\"3晚酒店\",\"行程用餐\",\"景点门票\"]','[\"个人消费\",\"单房差\",\"自费项目\"]',55,234,4.6,89,1,'2026-01-22 22:50:05','2026-02-12 22:22:07',0,'休闲游','海岛,美食,自然',0.00,NULL,0);
