DROP TABLE IF EXISTS `travel_note`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `travel_note` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL COMMENT '游记标题',
  `content` longtext,
  `cover_image` longtext,
  `user_id` bigint NOT NULL COMMENT '作者ID',
  `destination` varchar(50) DEFAULT NULL COMMENT '关联目的地',
  `locations` varchar(500) DEFAULT NULL COMMENT '途径地点JSON',
  `travel_date` date DEFAULT NULL COMMENT '出发日期',
  `days` int DEFAULT NULL COMMENT '游玩天数',
  `cost` decimal(10,2) DEFAULT NULL COMMENT '人均花费',
  `people` varchar(50) DEFAULT NULL COMMENT '人物(情侣/亲子/朋友)',
  `views` int DEFAULT '0' COMMENT '浏览量',
  `likes` int DEFAULT '0' COMMENT '点赞数',
  `favorites` int DEFAULT '0' COMMENT '收藏数',
  `comments` int DEFAULT '0' COMMENT '评论数',
  `status` tinyint DEFAULT '1' COMMENT '状态: 0-草稿 1-发布 2-审核中 3-违规',
  `review_time` datetime DEFAULT NULL,
  `reviewer_id` bigint DEFAULT NULL,
  `reject_reason` varchar(500) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  `favorite_count` int DEFAULT '0' COMMENT '收藏量',
  `review_status` tinyint DEFAULT '1' COMMENT '审核状态：0-待审核 1-已通过 2-已拒绝',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_destination` (`destination`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='游记表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `travel_note` WRITE;
/*!40000 ALTER TABLE `travel_note` DISABLE KEYS */;
INSERT INTO `travel_note` VALUES (1,'七月在云南，遇见最美的春天','<p>这是测试游记内容...</p>','https://picsum.photos/800/400?random=101',1,'云南',NULL,NULL,NULL,NULL,NULL,1207,56,0,0,1,NULL,NULL,NULL,'2026-01-24 23:14:58','2026-02-14 21:23:32',0,0,0),(2,'三亚潜水初体验，太美了！','<p>潜水真的很不可思议...</p>','https://picsum.photos/800/400?random=102',2,'海南',NULL,NULL,NULL,NULL,NULL,891,32,0,0,1,NULL,NULL,NULL,'2026-01-24 23:14:58','2026-02-14 21:23:32',0,0,0),(3,'博白游记','没毛','',5,'博白',NULL,NULL,NULL,NULL,NULL,2,0,0,0,1,NULL,NULL,NULL,'2026-01-30 22:25:34','2026-02-14 21:23:32',0,0,0),(4,'历史革命景点','我喜欢这里！！！','data:image/jpeg;base64,',5,'上海',NULL,'2026-02-18',2,555.00,NULL,1,0,0,0,1,NULL,NULL,NULL,'2026-02-12 22:13:21','2026-02-14 21:23:32',0,0,0);
/*!40000 ALTER TABLE `travel_note` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `travel_note_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `travel_note_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `note_id` bigint NOT NULL COMMENT '游记ID',
  `user_id` bigint NOT NULL COMMENT '评论用户ID',
  `content` text NOT NULL COMMENT '评论内容',
  `parent_id` bigint DEFAULT NULL COMMENT '父评论ID(回复)',
  `reply_to_uid` bigint DEFAULT NULL COMMENT '被回复用户ID',
  `likes` int DEFAULT '0' COMMENT '点赞数',
  `status` tinyint DEFAULT '1' COMMENT '状态: 0-隐藏 1-正常',
  `review_time` datetime DEFAULT NULL,
  `reviewer_id` bigint DEFAULT NULL,
  `reject_reason` varchar(500) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  `review_status` tinyint DEFAULT '1' COMMENT '审核状态：0-待审核 1-已通过 2-已拒绝',
  PRIMARY KEY (`id`),
  KEY `idx_note_id` (`note_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='游记评论表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `travel_note_comment` WRITE;
/*!40000 ALTER TABLE `travel_note_comment` DISABLE KEYS */;
/*!40000 ALTER TABLE `travel_note_comment` ENABLE KEYS */;
